import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------- Elementwise addition custom CUDA operator ----------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

elementwise_add_cpp_source = "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"

elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

# ---------- Reverse cumulative sum custom CUDA operator ----------
reverse_cumsum_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void reverse_cumsum_kernel(const float* data, float* out, int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        float sum = 0.0f;
        for (int j = idx; j < total_elements; ++j) {
            sum += data[j];
        }
        out[idx] = sum;
    }
}

torch::Tensor reverse_cumsum_cuda(torch::Tensor x, int dim) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    reverse_cumsum_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

reverse_cumsum_cpp_source = "torch::Tensor reverse_cumsum_cuda(torch::Tensor x, int dim);"

reverse_cumsum = load_inline(
    name="reverse_cumsum_cuda",
    cpp_sources=reverse_cumsum_cpp_source,
    cuda_sources=reverse_cumsum_source,
    functions=["reverse_cumsum_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

class ModelNew(nn.Module):
    def __init__(self, dim):
        super().__init__()
        self.dim = dim
        self.elementwise_add = elementwise_add
        self.reverse_cumsum_cuda = reverse_cumsum

    def forward(self, x):
        # Flip the input along the specified dimension
        x_flipped = x.flip(self.dim)
        # Apply custom reverse‑cumulative‑sum kernel
        out = self.reverse_cumsum_cuda(x_flipped, self.dim)
        # Flip the result back to the original layout
        return out.flip(self.dim)

def get_inputs():
    batch_size = 32768
    input_shape = (32768,)
    a = torch.randn(batch_size, *input_shape).cuda()
    return [a]

def get_init_inputs():
